pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 amountEther) public {
        amountEther = bound(amountEther, 0, type(uint120).max);
        vm.assume(amountEther != 10);
        uint256 exactAmount = 10 ether;
        address caller = address(0x1234);
        vm.deal(caller, exactAmount * 2);

        vm.roll(16);
        vm.warp(100);

        vm.prank(caller);
        (bool success1, ) = address(c).call{value: exactAmount}("");
        require(success1, "first fallback failed");

        uint256 tsAfter = c.pastBlockTime();
        assertTrue(tsAfter > block.timestamp);
    }
}
